 auto next=state_;auto m=modal_;  std::string src=b.source; std::transform(src.begin(),src.end(),src.begin(),[](unsigned char c){return char(std::toupper(c));});  if(src.find("TRAORI")!=std::string::npos) m.traori=true;  if(src.find("TRAFOOF")!=std::string::npos) m.traori=false;double f=feed_,s=rpm_;int t=tool_,d=d_;bool move=false; bool cycle_done=false; double cycle_r=0; bool cycle_r_set=false; ArcDefinition arc{}; Vec3 tool_axis{}; bool has_tool_axis=false;
